from pathlib import Path
q=Path('models/build/incremental_build.qnt')
q.write_text(q.read_text()+'''\n// Static population inventory, NOT a scheduler/refinement theorem. The 34\n// Scheme-to-C targets are separate from their 34 C-to-object actions. Runtime\n// library, configured headers, boot producer and normal objects are external.\nmodule gsc_population {\n  val GenerationTargets = 0.to(33)\n  val LibraryTargets = 0.to(32)\n  val PopulationNodes = 0.to(73)\n  pure def populationDeps(n: int): Set[int] =\n    if (n < 34) Set()\n    else if (n < 68) Set(n - 34)\n    else if (n == 68) LibraryTargets\n    else if (n == 69) Set(68)\n    else if (n == 70) 34.to(66).union(Set(69))\n    else if (n == 71) Set(33, 68)\n    else if (n == 72) Set(71)\n    else Set(67, 70, 72)\n  // Make LIBRARY_MODULES order: _utils=1, _t-c-3=31. Values are\n  // injection into this inventory, NOT a many-to-one simulation of execution.\n  val selectedInjection = Map(0 -> 31, 1 -> 1, 2 -> 65, 3 -> 35,\n    4 -> 68, 5 -> 69, 6 -> 70, 7 -> 71, 8 -> 72, 9 -> 73)\n  val missingBoundaryEdges = Set((33, 71), (67, 73))\n  val omittedLibraryTargets = LibraryTargets.exclude(Set(1, 31))\n  val inventoryAcyclic = PopulationNodes.forall(n =>\n    populationDeps(n).forall(d => d < n))\n}\n\n// Chosen immutable-view protocol; tracking ALL invalidating writes and compiler\n// effects is an explicit environmental premise, not proved by epoch equality.\n// Input 0 is a selector; its value selects input 1 or 2. Old traces cannot\n// certify the new branch. Generated prerequisites are separately ready.\nmodule dependency_cut {\n  val Inputs = 0.to(2)\n  type CutState = { epoch: int, attemptEpoch: int, live: int -> int,\n    image: int -> int, cut: Set[int], observed: int -> int, ready: Set[int],\n    stage: int, groupComplete: bool, revoked: bool, admitted: bool }\n  var c: CutState\n  pure def needed(image: int -> int): Set[int] =\n    Set(0, if (image.get(0) == 0) 1 else 2)\n  pure def cutInitial: CutState = { epoch: 0, attemptEpoch: 0,\n    live: Inputs.mapBy(_ => 0), image: Inputs.mapBy(_ => 0),\n    cut: Set(), observed: Inputs.mapBy(_ => -1), ready: Set(0),\n    stage: 0, groupComplete: false, revoked: false, admitted: false }\n  action initCut = c' = cutInitial\n  action beginCut = all { c.stage == 0,\n    c' = { ...c, attemptEpoch: c.epoch, image: c.live, stage: 1 } }\n  action validateInput(i: int) = all { c.stage == 1, Inputs.contains(i),\n    c' = { ...c, ready: c.ready.union(Set(i)) } }\n  action observeInput(i: int) = all { c.stage == 1, c.ready.contains(i),\n    (i == 0 or (c.cut.contains(0) and needed(c.image).contains(i))),\n    c' = { ...c, cut: c.cut.union(Set(i)),\n      observed: c.observed.set(i, c.image.get(i)) } }\n  action sealCut = all { c.stage == 1, needed(c.image).subseteq(c.cut),\n    c.attemptEpoch == c.epoch, not(c.revoked),\n    c' = { ...c, stage: 2 } }\n  action stageGroup = all { c.stage == 2,\n    c' = { ...c, groupComplete: true, stage: 3 } }\n  action publishCut = all { c.stage == 3, c.groupComplete,\n    c.attemptEpoch == c.epoch, not(c.revoked),\n    c' = { ...c, stage: 4, admitted: true } }\n  action worldWrite(i: int) = all { Inputs.contains(i),\n    c' = { ...c, epoch: c.epoch + 1,\n      live: c.live.set(i, 1 - c.live.get(i)), revoked: true } }\n  action restartCut = all { c.revoked, c.stage != 4,\n    c' = { ...cutInitial, epoch: c.epoch, live: c.live } }\n  action cutStep = {\n    nondet i = Inputs.oneOf()\n    any { beginCut, validateInput(i), observeInput(i), sealCut, stageGroup,\n      publishCut, worldWrite(i), restartCut, c' = c }\n  }\n  val observationAgreement = c.cut.forall(i => c.observed.get(i) == c.image.get(i))\n  // Historical admission remains true after revocation; never CURRENT then.\n  val currentCut = c.admitted and not(c.revoked)\n  val cutPublicationSafe = currentCut implies all {\n    c.groupComplete, c.attemptEpoch == c.epoch,\n    needed(c.image).subseteq(c.cut), observationAgreement }\n}\n''')
p=Path('models/build/IncrementalBuild.lean');s=p.read_text();s=s.replace('end GambitBuild','''-- Increasing a conservative cut preserves extensional completeness. Finding\n-- a finite fixed point is separate from proving this semantic premise.\ntheorem agreementOnSmallerCut {Input Value : Type} {small large : Input → Prop}\n    {a b : Input → Value} (included : ∀ i, small i → large i)\n    (agreement : CutAgreement large a b) : CutAgreement small a b := by\n  intro i hi\n  exact agreement i (included i hi)\n\ntheorem completeCutCanGrow {Input Value Output : Type}\n    {small large : Input → Prop} {produce : (Input → Value) → Output}\n    (included : ∀ i, small i → large i) (complete : CutComplete small produce) :\n    CutComplete large produce := by\n  intro a b agreement\n  exact complete a b (agreementOnSmallerCut included agreement)\n\n-- An extension cannot remove an already required downstream invalidation.\ntheorem affectedEdgeExtension {Node : Type} {before after : Node → Node → Prop}\n    {changed : Node → Prop} {n : Node}\n    (included : ∀ a b, before a b → after a b)\n    (affected : Affected before changed n) : Affected after changed n := by\n  induction affected with\n  | source h => exact .source h\n  | consumer _ edge ih => exact .consumer ih (included _ _ edge)\n\ndef ObservationAgreement {Input Value : Type} (image : Input → Value)\n    (trace : List (Input × Value)) : Prop := ∀ p ∈ trace, p.2 = image p.1\n\ntheorem immutableReadExtendsTrace {Input Value : Type} {image : Input → Value}\n    {trace : List (Input × Value)} (sound : ObservationAgreement image trace)\n    (i : Input) : ObservationAgreement image ((i, image i) :: trace) := by\n  intro p hp\n  rcases List.mem_cons.mp hp with hp | hp\n  · subst p; rfl\n  · exact sound p hp\n\n-- A linearized epoch check is useful only if its issuer proves the following\n-- agreement. End-of-run equal hashes do not construct this premise.\ntheorem receiptReuseMatchesClean {Input Value Output : Type}\n    {cut : Input → Prop} {produce : (Input → Value) → Output}\n    {previous image current : Input → Value} {cached : Output}\n    (complete : CutComplete cut produce) (origin : cached = produce previous)\n    (traceValid : CutAgreement cut previous image)\n    (receipt : CutAgreement cut image current) : cached = produce current := by\n  apply reuseMatchesClean complete origin\n  intro i hi\n  exact (traceValid i hi).trans (receipt i hi)\n\n-- A family of observations, not one arbitrarily chosen metadata projection.\ntheorem allConsumerCutoff {Consumer Output View : Type}\n    (observe : Consumer → Output → View) {old fresh : Output}\n    (same : ∀ c, observe c old = observe c fresh)\n    (c : Consumer) (consume : View → View) :\n    consume (observe c old) = consume (observe c fresh) := by\n  exact congrArg consume (same c)\n\n-- Conditional forward simulation preserves a safety invariant. This reusable\n-- lemma supplies NO relation between actual GSC processes and either QNT model.\ntheorem projectedStepPreserves {Concrete Abstract : Type}\n    (project : Concrete → Abstract) (step : Concrete → Concrete → Prop)\n    (abstractStep : Abstract → Abstract → Prop) (safe : Abstract → Prop)\n    (simulate : ∀ a b, step a b →\n      abstractStep (project a) (project b) ∨ project a = project b)\n    (preserve : ∀ a b, safe a → abstractStep a b → safe b)\n    {a b : Concrete} (ha : safe (project a)) (hab : step a b) :\n    safe (project b) := by\n  rcases simulate a b hab with move | idle\n  · exact preserve _ _ ha move\n  · rw [← idle]; exact ha\n\nend GambitBuild''');p.write_text(s)
